const DEFAULT_STATE = { habits: [], records: {}, version: 1 };

function pad2(n) {
  return n < 10 ? '0' + n : String(n);
}

function todayKey() {
  const d = new Date();
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
}

function todayLabel() {
  const d = new Date();
  const week = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
  return d.getFullYear() + ' 年 ' + (d.getMonth() + 1) + ' 月 ' + d.getDate() + ' 日 · ' + week[d.getDay()];
}

function makeId() {
  return 'h_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
}

function normalizeState(raw) {
  const base = Object.assign({}, DEFAULT_STATE, raw && typeof raw === 'object' ? raw : {});
  if (!Array.isArray(base.habits)) base.habits = [];
  base.habits = base.habits
    .filter(function (h) { return h && typeof h === 'object'; })
    .map(function (h) {
      return Object.assign({}, h, {
        id: typeof h.id === 'string' && h.id ? h.id : makeId(),
        name: typeof h.name === 'string' ? h.name : String(h.name == null ? '' : h.name),
        createdAt: typeof h.createdAt === 'string' ? h.createdAt : new Date().toISOString()
      });
    });
  if (!base.records || typeof base.records !== 'object' || Array.isArray(base.records)) base.records = {};
  const cleaned = {};
  Object.keys(base.records).forEach(function (day) {
    const val = base.records[day];
    if (val && typeof val === 'object' && !Array.isArray(val)) {
      const dayMap = {};
      Object.keys(val).forEach(function (hid) {
        if (val[hid]) dayMap[hid] = true;
      });
      cleaned[day] = dayMap;
    }
  });
  base.records = cleaned;
  return base;
}

const els = {
  todayLabel: app.querySelector('[data-role="today-label"]'),
  doneCount: app.querySelector('[data-role="done-count"]'),
  totalCount: app.querySelector('[data-role="total-count"]'),
  progressbar: app.querySelector('[data-role="progressbar"]'),
  progressFill: app.querySelector('[data-role="progress-fill"]'),
  statHint: app.querySelector('[data-role="stat-hint"]'),
  addForm: app.querySelector('[data-role="add-form"]'),
  nameInput: app.querySelector('[data-role="name-input"]'),
  addBtn: app.querySelector('[data-role="add-btn"]'),
  addMsg: app.querySelector('[data-role="add-msg"]'),
  listCount: app.querySelector('[data-role="list-count"]'),
  listError: app.querySelector('[data-role="list-error"]'),
  habitList: app.querySelector('[data-role="habit-list"]'),
  emptyTip: app.querySelector('[data-role="empty-tip"]')
};

let state = normalizeState(await appStore.getState());
let pendingDeleteId = null;
let busy = false;

function setAddMsg(text, isError) {
  els.addMsg.textContent = text || '';
  els.addMsg.classList.toggle('msg-error', !!isError);
}

function setListError(text) {
  if (text) {
    els.listError.textContent = text;
    els.listError.hidden = false;
  } else {
    els.listError.textContent = '';
    els.listError.hidden = true;
  }
}

function isDoneToday(habitId) {
  const day = state.records[todayKey()];
  return !!(day && day[habitId]);
}

function renderStats() {
  const total = state.habits.length;
  const done = state.habits.filter(function (h) { return isDoneToday(h.id); }).length;
  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  const pct = total > 0 ? Math.round((done / total) * 100) : 0;
  els.progressFill.style.width = pct + '%';
  els.progressbar.setAttribute('aria-valuenow', String(pct));
  els.listCount.textContent = '共 ' + total + ' 个';

  if (total === 0) {
    els.statHint.textContent = '还没有习惯，先添加一个吧。';
  } else if (done === total) {
    els.statHint.textContent = '太棒了，今天的习惯全部完成！';
  } else {
    els.statHint.textContent = '还有 ' + (total - done) + ' 个习惯等待完成。';
  }
}

function renderList() {
  els.habitList.textContent = '';
  const total = state.habits.length;
  els.emptyTip.hidden = total > 0;

  state.habits.forEach(function (habit) {
    const done = isDoneToday(habit.id);

    const li = document.createElement('li');
    li.className = 'habit-item' + (done ? ' is-done' : '');

    const label = document.createElement('label');
    label.className = 'habit-check';

    const box = document.createElement('input');
    box.type = 'checkbox';
    box.checked = done;
    box.setAttribute('aria-label', '标记「' + habit.name + '」今天已完成');
    box.addEventListener('change', function () {
      toggleHabit(habit.id, box.checked);
    });

    const nameSpan = document.createElement('span');
    nameSpan.className = 'habit-name';
    nameSpan.textContent = habit.name;

    label.appendChild(box);
    label.appendChild(nameSpan);

    const meta = document.createElement('span');
    meta.className = 'habit-meta';
    meta.textContent = done ? '今日已完成' : '今日未完成';

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'btn-del' + (pendingDeleteId === habit.id ? ' is-confirm' : '');
    delBtn.textContent = pendingDeleteId === habit.id ? '确认删除' : '删除';
    delBtn.addEventListener('click', function () {
      requestDelete(habit.id);
    });

    li.appendChild(label);
    li.appendChild(meta);
    li.appendChild(delBtn);
    els.habitList.appendChild(li);
  });
}

function render() {
  renderStats();
  renderList();
}

async function persist(next) {
  await appStore.setState(next);
  state = normalizeState(next);
}

async function toggleHabit(habitId, checked) {
  if (busy) return;
  busy = true;
  setListError('');
  const key = todayKey();
  const next = normalizeState(state);
  const day = Object.assign({}, next.records[key] || {});
  if (checked) {
    day[habitId] = true;
  } else {
    delete day[habitId];
  }
  next.records[key] = day;
  try {
    await persist(next);
    render();
  } catch (err) {
    setListError('保存失败，打卡状态未改变，请重试。');
    render();
  } finally {
    busy = false;
  }
}

async function requestDelete(habitId) {
  if (busy) return;
  if (pendingDeleteId !== habitId) {
    pendingDeleteId = habitId;
    setListError('');
    renderList();
    return;
  }
  pendingDeleteId = null;
  busy = true;
  setListError('');
  const next = normalizeState(state);
  next.habits = next.habits.filter(function (h) { return h.id !== habitId; });
  Object.keys(next.records).forEach(function (day) {
    if (next.records[day] && next.records[day][habitId]) {
      const dayMap = Object.assign({}, next.records[day]);
      delete dayMap[habitId];
      next.records[day] = dayMap;
    }
  });
  try {
    await persist(next);
    render();
  } catch (err) {
    setListError('删除失败，习惯仍然保留，请重试。');
    render();
  } finally {
    busy = false;
  }
}

els.addForm.addEventListener('submit', async function (event) {
  event.preventDefault();
  if (busy) return;
  const raw = els.nameInput.value;
  const name = raw.trim();
  if (!name) {
    setAddMsg('请输入习惯名称。', true);
    els.nameInput.focus();
    return;
  }
  const exists = state.habits.some(function (h) {
    return h.name.trim().toLowerCase() === name.toLowerCase();
  });
  if (exists) {
    setAddMsg('已经有同名习惯了，换一个名字吧。', true);
    els.nameInput.focus();
    return;
  }

  busy = true;
  els.addBtn.disabled = true;
  setAddMsg('');
  const next = normalizeState(state);
  next.habits = next.habits.concat([{
    id: makeId(),
    name: name,
    createdAt: new Date().toISOString()
  }]);

  try {
    await persist(next);
    els.nameInput.value = '';
    setAddMsg('已添加「' + name + '」。', false);
    render();
  } catch (err) {
    setAddMsg('保存失败，习惯未添加，请重试。', true);
  } finally {
    busy = false;
    els.addBtn.disabled = false;
    els.nameInput.focus();
  }
});

els.todayLabel.textContent = todayLabel();
render();

