* { box-sizing: border-box; }

.wrap {
  max-width: 640px;
  margin: 0 auto;
  padding: 20px 16px 40px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  font-family: system-ui, -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  color: #1f2933;
}

.hero { padding: 4px 2px 0; }

.hero-title {
  margin: 0;
  font-size: 26px;
  line-height: 1.25;
  letter-spacing: 0.5px;
}

.hero-date {
  margin: 6px 0 0;
  font-size: 14px;
  color: #6b7785;
}

.card {
  background: #ffffff;
  border: 1px solid #e6e9ee;
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 1px 2px rgba(31, 41, 51, 0.04);
}

.card-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 600;
}

.stat-card { display: flex; flex-direction: column; gap: 10px; }

.stat-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
}

.stat-num {
  font-size: 34px;
  font-weight: 700;
  color: #2f7d5d;
  line-height: 1;
}

.stat-sep, .stat-total {
  font-size: 18px;
  color: #8a94a1;
}

.stat-unit {
  font-size: 14px;
  color: #6b7785;
  margin-left: 4px;
}

.progress {
  height: 8px;
  border-radius: 999px;
  background: #eef1f5;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, #4fb286, #2f7d5d);
  transition: width 0.25s ease;
}

.stat-hint {
  margin: 0;
  font-size: 13px;
  color: #6b7785;
}

.add-form {
  display: flex;
  gap: 10px;
  align-items: flex-end;
  flex-wrap: wrap;
}

.field {
  flex: 1 1 200px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: #4a5560;
  font-weight: 500;
}

.input {
  width: 100%;
  padding: 10px 12px;
  font-size: 15px;
  color: #1f2933;
  background: #fbfcfd;
  border: 1px solid #d7dde5;
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.input:focus {
  border-color: #4fb286;
  box-shadow: 0 0 0 3px rgba(79, 178, 134, 0.18);
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 15px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn-primary {
  background: #2f7d5d;
  color: #ffffff;
  white-space: nowrap;
}

.btn-primary:hover { background: #276a4f; }
.btn-primary:active { background: #215a43; }

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.msg {
  margin: 10px 0 0;
  font-size: 13px;
  min-height: 18px;
  color: #2f7d5d;
}

.msg-error { color: #c0392b; }

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-head .card-title { margin-bottom: 12px; }

.list-count {
  font-size: 13px;
  color: #8a94a1;
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid #e6e9ee;
  border-radius: 12px;
  background: #fbfcfd;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.habit-item.is-done {
  background: #f1f9f5;
  border-color: #bfe3d1;
}

.habit-check {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  cursor: pointer;
}

.habit-check input[type="checkbox"] {
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  accent-color: #2f7d5d;
  cursor: pointer;
}

.habit-name {
  font-size: 15px;
  line-height: 1.4;
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: #2f7d5d;
  text-decoration: line-through;
  text-decoration-color: rgba(47, 125, 93, 0.5);
}

.habit-meta {
  font-size: 12px;
  color: #8a94a1;
  white-space: nowrap;
}

.btn-del {
  flex: 0 0 auto;
  background: #ffffff;
  border: 1px solid #e2c3bf;
  color: #c0392b;
  border-radius: 9px;
  padding: 6px 10px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
}

.btn-del:hover { background: #fdf3f2; }

.btn-del.is-confirm {
  background: #c0392b;
  border-color: #c0392b;
  color: #ffffff;
}

.empty {
  margin: 4px 0 0;
  font-size: 14px;
  color: #8a94a1;
  line-height: 1.6;
}

.footer-note {
  margin: 0;
  text-align: center;
  font-size: 12px;
  color: #9aa4b0;
}

@media (max-width: 420px) {
  .stat-num { font-size: 30px; }
  .add-form { flex-direction: column; align-items: stretch; }
  .btn-primary { width: 100%; }
}
